INSERT INTO `catalog_productseo` (`id`, `meta_title`, `meta_description`, `meta_image`, `product_id`, `canonical_url`, `meta_keywords`) VALUES
(903, '360° TV Wall Mount | Heavy Duty Adjustable VESA Bracket', '360° TV Wall Mount offers adjustable rotation, heavy-duty construction and VESA compatibility for secure flat panel displays in homes, offices and workspaces.', 'products/seo/SH_360R_Detail_Pic_01.jpg', 966, 'https://skilltechonline.com/tv-wall-mount/fixed-flat-wall-mounts/sh-360r', '360° TV Wall Mount'),
(904, 'Landscape/Portrait TV Wall Mount | VESA Display Bracket', 'Landscape/Portrait TV Wall Mount supports VESA-compatible flat panel and interactive displays with strong, durable construction for offices and workspaces.', 'products/seo/SH_46UFR_Detail_Pic_01.jpg', 967, 'https://www.skilltechonline.com/tv-wall-mount/fixed-flat-wall-mounts/sh-46ufr', 'Landscape Portrait TV Wall Mount'),
(905, 'XX-Large Heavy Duty Fixed TV Wall Mount | VESA Bracket', 'XX-Large Heavy Duty Fixed TV Wall Mount offers strong, durable VESA-compatible support for flat panel displays in homes, offices, retail and commercial spaces.', 'products/seo/SH_2200F_Detail_Pic.jpg', 968, 'https://www.skilltechonline.com/tv-wall-mount/fixed-flat-wall-mounts/sh-2200f', 'Heavy Duty Fixed TV Mount'),
(906, 'Ultra Slim Micro-Gap Fixed TV Wall Mount | VESA Bracket', 'Ultra Slim Micro-Gap Fixed TV Wall Mount offers a sleek, secure fit with strong, durable VESA-compatible support for flat panel displays in homes and offices.', 'products/seo/SH_LED_01.jpg', 969, 'https://www.skilltechonline.com/tv-wall-mount/fixed-flat-wall-mounts/sh-led-01', 'Micro-Gap TV Wall Mount'),
(907, 'Heavy-Duty Fixed TV Wall Mount | VESA Flat Bracket', 'Heavy-Duty Fixed TV Wall Mount with strong, durable construction and VESA compatibility for secure flat panel displays in homes, offices and commercial spaces.', 'products/seo/SH_1208F.webp', 970, 'https://www.skilltechonline.com/tv-wall-mount/fixed-flat-wall-mounts/sh-1208f', 'Heavy Duty Fixed TV Mount'),
(908, 'Extra Large Heavy Duty Flat TV Wall Mount | VESA Bracket', 'Extra Large Heavy Duty Flat TV Wall Mount offers strong, durable VESA-compatible support for flat panel displays in homes, offices and commercial spaces.', 'products/seo/SH_1100F.jpg', 971, 'https://www.skilltechonline.com/tv-wall-mount/fixed-flat-wall-mounts/sh-1100f', 'Heavy Duty Flat TV Mount'),
(909, 'Heavy Duty Flat TV Wall Mount with Auto Lock | VESA Bracket', 'Heavy Duty Flat TV Wall Mount with Auto Lock offers strong, durable VESA-compatible support for flat panel displays in homes, offices and commercial spaces.', 'products/seo/SH_96F.webp', 972, 'https://www.skilltechonline.com/tv-wall-mount/fixed-flat-wall-mounts/sh-96f', 'Heavy Duty Flat TV Mount'),
(910, 'Fixed LCD/LED/Curved TV Wall Mount | VESA Flat Bracket', 'Fixed LCD/LED/Curved TV Wall Mount offers strong, durable VESA-compatible support for flat panel displays, ideal for homes, offices and commercial spaces.', 'products/seo/SH_1060F_Lew2wd2.webp', 973, 'https://www.skilltechonline.com/tv-wall-mount/fixed-flat-wall-mounts/sh-1060f', 'Fixed TV Wall Mount'),
(911, 'Fixed TV Wall Mount 55 Inch | Flat Panel Displays', 'Secure your 55-inch screen with a fixed TV wall mount suitable for flat panel displays. Ideal for home, office, retail, and commercial installations.', 'products/seo/8060F.jpg', 974, 'https://skilltechonline.com/', 'fixed TV wall mount 55 inch, 55 inch TV wall mount, fixed TV wall mount, 55 inch wall mount bracket, flat panel TV wall mount, flat panel display wall mount, LCD LED TV wall mount, low profile TV wall mount, VESA compatible TV mount, commercial TV wall mount, heavy duty TV wall bracket, digital signage wall mount, monitor wall mount UAE, TV wall mount UAE, office TV wall mount, conference room display mount, retail display wall mount, hospitality TV wall mount, professional TV mounting solution, AV mounting solutions UAE, TV wall mount supplier UAE, TV wall mount distributor UAE, B2B TV wall mount UAE, buy 55 inch TV wall mount UAE, commercial display mounting solutions UAE'),
(912, 'Fixed TV Wall Mount for Flat Panel Displays | Skill Mount', 'Secure your screen with a fixed TV wall mount suitable for flat panel displays. Ideal for residential, commercial, office, and retail installations.', 'products/seo/106F.jpg', 975, 'https://skilltechonline.com/', 'fixed TV wall mount, TV wall mount, flat panel TV wall mount, flat panel display wall mount, fixed wall mount bracket, low profile TV wall mount, VESA compatible TV mount, LCD LED TV wall mount, commercial TV wall mount, heavy duty TV wall bracket, digital signage wall mount, monitor wall mount UAE, TV wall mount UAE, office TV wall mount, conference room display mount, retail display wall mount, hospitality TV wall mount, professional TV mounting solution, AV mounting solutions UAE, TV wall mount supplier UAE, TV wall mount distributor UAE, B2B TV wall mount UAE, buy fixed TV wall mount UAE, commercial display mounting solutions UAE, wall mount for flat panel displays'),
(913, 'Portrait Mode Fixed TV Wall Mount | VESA Flat Bracket', 'Portrait Mode Fixed TV Wall Mount offers strong, durable VESA-compatible support for flat panel displays, ideal for offices, retail, signage and workspaces.', 'products/seo/64AF.jpg', 976, 'https://www.skilltechonline.com/tv-wall-mount/fixed-flat-wall-mounts/sh-64af', 'Portrait TV Wall Mount'),
(914, 'Portrait Display Wall Mount | Fixed VESA TV Bracket', 'Portrait Display Wall Mount with strong, durable construction and VESA compatibility for flat panel displays in retail, offices, signage and workspaces.', 'products/seo/906VF.jpg', 977, 'https://www.skilltechonline.com/tv-wall-mount/fixed-flat-wall-mounts/sh-906vf', 'Portrait Display Wall Mount'),
(916, 'Fixed TV Wall Mount | Slim VESA Bracket for Flat Displays', 'Fixed TV Wall Mount delivers strong, durable VESA-compatible support for flat panel displays, ideal for homes, offices, retail areas and organized workspaces.', 'products/seo/PM_75FW.jpg', 979, 'https://www.skilltechonline.com/tv-wall-mount/fixed-flat-wall-mounts/pm-75fw', 'Flat TV Wall Mount'),
