(1579, '12U Wall Mount Rack with Glass Door for Network & CCTV', '12U Wall Mount Rack with 19-inch compatibility, tempered glass front door, durable steel build, ventilation and cable management for CCTV and network setups.', 'products/seo/iL-C1209.jpg', 1666, 'https://skilltechonline.com/other-mounts-accessories/wall-mount-rack/il-c1209', '12U Wall Mount Rack'),
(1580, '15U Floor Standing Rack for Network & Server Equipment', '15U Floor Standing Rack with 15U capacity, 19-inch compatibility, heavy-duty construction and easy mobility for secure network, CCTV and server installations.', 'products/seo/iL-C1501.jpg', 1667, 'https://skilltechonline.com/other-mounts-accessories/wall-mount-rack/il-c1501', '15U Floor Standing Rack'),
(1581, '32 Inch Frameless LED TV with HD Ready Picture Quality', '32 Inch Frameless LED TV with Full HD picture quality, wide viewing angle, vivid color and contrast for reliable home, office and everyday television use.', 'products/seo/SK3200NT.jpg', 1604, 'https://skilltechonline.com/tv/normal/sk3200nt', '32 Inch Frameless LED TV'),
(1582, '40 Inch Smart Full HD Frameless LED TV with Android Wi-Fi', '40 Inch Smart Full HD Frameless LED TV with Full HD resolution, wide viewing angle, Smart Android TV, built-in Wi-Fi and multiple connectivity options.', 'products/seo/SK4040SFL.jpg', 1608, 'https://skilltechonline.com/tv/smart-tv/sk4040sfl', '40 Inch Smart Full HD TV'),
(1583, '43 Inch IR Touch Digital Signage Kiosk for Interactive Use', '43 Inch Digital Signage Kiosk with vibrant IR touch display, powerful performance and sleek durable design for retail, wayfinding and interactive use.', 'products/seo/SH_TK4305.jpg', 1638, 'https://skilltechonline.com/kiosk-screen/kiosk-touch/sh-tk4305', '43 Inch Digital Signage Kiosk'),
(1584, '55 Inch IR Touch Digital Signage Kiosk with 4K Display', '55 Inch Digital Signage Kiosk with 4K Ultra HD display, responsive IR touch and powerful Android performance for retail, wayfinding and interactive use.', 'products/seo/SH_TK5505.jpg', 1640, 'https://skilltechonline.com/kiosk-screen/kiosk-touch/sh-tk5505', '55 Inch Digital Signage Kiosk'),
(1585, '65 Inch IR Touch Digital Signage Kiosk with 4K Display', '65 Inch Digital Signage Kiosk with vibrant 4K display, IR touch, Android performance and durable commercial design for retail and interactive spaces use.', 'products/seo/SH_TK6505.jpg', 1645, 'https://skilltechonline.com/kiosk-screen/kiosk-touch/sh-tk6505', '65 Inch Digital Signage Kiosk'),
(1586, '0.5m CAT6+ Patch Cable for High-Speed Gigabit Ethernet', '0.5m CAT6+ Patch Cable delivers high-speed Gigabit Ethernet, reliable data transfer and stable connectivity for routers, switches, PCs and network devices.', 'products/seo/SH_CAT6_23_00.5M.jpg', 1541, 'https://skilltechonline.com/hdmi-cables/hdmi-cables/sh-cat6-23-005m', 'CAT6+ Patch Cable'),
(1587, '1m CAT6+ Patch Cable for High-Speed Gigabit Ethernet', '1m CAT6+ Patch Cable delivers high-speed Gigabit performance, extended transmission distance, optimized Ethernet connectivity and high data transfer rates.', 'products/seo/SH_CAT6_23_001M.jpg', 1542, 'https://skilltechonline.com/other-cables/cat6-patch-cable/sh-cat6-23-001m', 'CAT6+ Patch Cable'),
(1588, '2m CAT6+ Patch Cable for High-Speed Gigabit Ethernet', '2m CAT6+ Patch Cable delivers high-speed Gigabit performance, extended transmission distance, optimized Ethernet connectivity and fast, reliable data transfer.', 'products/seo/SH_CAT6_23_002M.jpg', 1543, 'https://skilltechonline.com/other-cables/cat6-patch-cable/sh-cat6-23-002m', 'CAT6+ Patch Cable'),
(1589, '3m CAT6+ Patch Cable for Fast Gigabit Network Connections', '3m CAT6+ Patch Cable offers high-speed Gigabit performance, extended reach, optimized Ethernet connectivity and reliable high data transfer for network setups.', 'products/seo/SH_CAT6_23_003M.jpg', 1544, 'https://skilltechonline.com/other-cables/cat6-patch-cable/sh-cat6-23-003m', '3m CAT6+ Patch Cable'),
(1590, '5m CAT6+ Patch Cable for High-Speed Gigabit Ethernet', '5m CAT6+ Patch Cable delivers high-speed Gigabit performance, extended transmission distance, optimized Ethernet connectivity and reliable data transfer.', 'products/seo/SH_CAT6_23_005M.jpg', 1545, 'https://skilltechonline.com/other-cables/cat6-patch-cable/sh-cat6-23-05m', '5m CAT6+ Patch Cable'),
(1591, '10m CAT6+ Patch Cable for High-Speed Gigabit Ethernet', '10m CAT6+ Patch Cable offers high-speed Gigabit performance, extended transmission distance, optimized Ethernet connectivity and reliable data transfer.', 'products/seo/SH_CAT6_23_010M.jpg', 1546, 'https://skilltechonline.com/other-cables/cat6-patch-cable/sh-cat6-23-010m', '10m CAT6+ Patch Cable'),
(1592, '1.5M DisplayPort to DisplayPort Cable for High-Resolution AV', '1.5M DisplayPort Cable supports high-resolution video and clear audio transmission, with flexible connectivity for PCs, laptops, monitors and projectors.', 'products/seo/SH_DP_001.5M.jpg', 1521, 'https://skilltechonline.com/hdmi-cables/dp-cables/sh-dp-0015m', 'DisplayPort Cable'),
(1593, '3M DisplayPort Cable for High-Resolution Audio & Video', '3M DisplayPort Cable delivers high-resolution visuals and stable audio-video transmission, ideal for gaming, office work, monitors, laptops and multimedia use.', 'products/seo/SH_DP_003M.jpg', 1522, 'https://skilltechonline.com/hdmi-cables/dp-cables/sh-dp-oo3m', '3M DisplayPort Cable'),
(1594, '5M DisplayPort Cable for High-Resolution Audio & Video', '5M DisplayPort Cable delivers high-resolution visuals, stable audio-video transmission and extended reach for flexible gaming, office and multimedia setups.', 'products/seo/SH_DP_005M.jpg', 1523, 'https://skilltechonline.com/hdmi-cables/dp-cables/sh-dp-005m', '5M DisplayPort Cable'),
(1595, 'USB Type-C Female to Female High-Speed Extension Cable 23cm', 'USB Type-C Female to Female cable with bare copper conductors and compact 23 cm length, ideal for high-speed USB-C extension, charging and data connections.', 'products/seo/usb_14.jpg', 1625, 'https://skilltechonline.com/other-mounts-accessories/other-mounts/il-usbcp14', 'USB-C Extension Cable'),
(1596, '8MP Video Balun with Pigtail Press-Fit for CCTV Systems', '8MP Video Balun supports up to 8MP resolution, multi-format compatibility and up to 300 m transmission, with a pigtail press-fit design for secure CCTV setups.', 'products/seo/iL-VB1_._8MP.jpg', 1619, 'https://skilltechonline.com/other-mounts-accessories/other-mounts/il-vb1-8mp', '8MP Video Balun'),
(1597, 'HDMI Female-to-Female Pigtail Cable 23cm for 4K HDMI 2.0', 'HDMI Pigtail cable with female-to-female connection, HDMI 2.0 support and 4K resolution. Compact 23 cm design for clean, flexible AV extensions and setups.', 'products/seo/iL-_HDMI_P12.jpg', 1609, 'https://skilltechonline.com/cctv-camera-brackets/ceilling-mounts/il-hdmi-p12', 'HDMI Female to Female Cable');
