(9, 'home', 'Skill Tech | Global Professional AV & Display Solutions UAE', 'Global provider of AV solutions, display mounting systems, LED displays, digital signage, commercial displays and AV accessories for every project.', 'seo/logo_1200x1200.jpg', 'Professional AV Solutions', 'https://skilltechonline.com/'),
(10, 'about', 'About Skill Tech | Global Professional AV Solutions', 'Learn about Skill Tech, a global provider of professional AV solutions, display technology, mounting systems and AV accessories. Partner with us today.', '', 'Global AV Solutions Provider', 'https://skilltechonline.com/about'),
(11, 'services', 'Professional TV Installation Services UAE | Skill Tech', 'Professional TV installation, secure wall mounting and AV setup for homes and businesses. Expert technicians for reliable service. Book today.', '', 'TV Installation Service', 'https://skilltechonline.com/service'),
(12, 'support', 'Skill Tech Support | Expert AV Technical Assistance', 'Get expert product support, technical assistance, installation guidance and after-sales service for Skill Tech AV solutions. Contact our support team today.', '', 'AV Technical Support', 'https://skilltechonline.com/support'),
(13, 'gallery', 'Skill Tech Gallery | AV Projects & Installation Showcase', 'Explore Skill Tech\'s completed AV projects, display installations, LED displays, video walls and mounting solutions. See our expertise in action.', '', 'AV Projects', 'https://skilltechonline.com/gallery');
