INSERT INTO `catalog_subcategory` (`id`, `name`, `slug`, `image`, `category_id`, `active`, `order`, `multi_expand`, `canonical_url`, `meta_description`, `meta_image`, `meta_keywords`, `meta_title`, `name_ar`) VALUES
(44, 'Fixed / Flat Wall Mounts', 'fixed-flat-wall-mounts', 'subcategories/2_1c1d1b8b31e7c6c5f5f4288d064751815_CVo54HV.jpg', 43, 1, 0.000, 0, 'https://skilltechonline.com/tv-wall-mount/fixed-flat-wall-mounts', 'Buy fixed TV wall mounts in UAE with slim profiles, VESA compatibility, sturdy steel builds and heavy-duty support for secure flat and curved TV setups.', 'subcategories/seo/Fixed_and_Flat_Wall_Mount.jpg', 'Fixed TV Wall Mounts UAE', 'Fixed TV Wall Mounts UAE | Slim & Heavy-Duty | Skill Tech', 'حوامل حائط ثابتة/مسطحة'),
(45, 'Tilt Wall Mounts', 'tilt-wall-mounts', 'subcategories/SH_105T_scene-pic_01.jpg', 43, 1, 1.000, 0, 'https://skilltechonline.com/tv-wall-mount/tilt-wall-mounts', 'Buy tilt TV wall mounts in UAE with adjustable viewing angles, VESA support, durable steel construction and low-profile designs for flat and curved TVs.', 'subcategories/seo/Tilt_Wall_Mounts.jpg', 'Tilt TV Wall Mounts UAE', 'Tilt TV Wall Mounts UAE | Heavy-Duty Range | Skill Tech', 'حوامل حائط قابلة للإمالة'),
(46, 'Full Motion Single Arm', 'full-motion-single-arm', 'subcategories/sing65e7e38fd869f4675114613034b73c87_VBWxEW4.jpg', 43, 1, 2.000, 0, 'https://skilltechonline.com/tv-wall-mount/full-motion-single-arm', 'Buy full motion single arm TV mounts in UAE with tilt, swivel, long extension, VESA support and durable steel builds for flexible home and commercial viewing.', 'subcategories/seo/Full_Motion_Single_Arm.jpg', 'Full Motion Single Arm TV Mounts UAE', 'Full Motion Single Arm TV Mounts UAE | Skill Tech Dubai', 'ذراع واحدة كاملة الحركة'),
(47, 'Full Motion Double Arm Mounts', 'full-motion-double-arm-mounts', 'subcategories/double5d96ca0cee4025f18d9048c24bd5a2b5.jpg', 43, 1, 3.000, 0, 'https://skilltechonline.com/tv-wall-mount/full-motion-double-arm-mounts', 'Buy full motion double arm TV mounts in UAE with heavy-duty steel builds, wide VESA support, tilt, swivel and long extension for flexible large-screen viewing.', 'subcategories/seo/Full_Motion_Double_Arm_Mounts.jpg', 'Full Motion Double Arm TV Mounts UAE', 'Full Motion Double Arm TV Mounts UAE | Skill Tech Dubai', 'حوامل مزدوجة الذراع كاملة الحركة'),
(48, 'Other Mounts & Accessories', 'other-mounts', 'subcategories/SH_XMA14_matte-black_scene-pic_01.jpg', 63, 1, 2.000, 0, 'https://skilltechonline.com/other-mounts-accessories/other-mounts', 'Shop Other Mounts & Accessories in UAE, including wall mount racks, VESA adapters, video wall parts, media mounts and AV accessories for professional setups.', 'subcategories/seo/Other_Mounts__Accessories_BzgdH0F.jpg', 'Other Mounts & Accessories UAE', 'Other Mounts & Accessories UAE Supplier | Skill Tech', 'حوامل وملحقات أخرى'),
(49, 'Articulating Monitor Arm', 'articulating-monitor-arm', 'subcategories/artic605995cb202f6611516996095e237eac_ZVDJPwR.jpg', 44, 1, 0.000, 1, 'https://skilltechonline.com/desktop-mounts/articulating-monitor-arm', 'Buy articulating monitor arms in UAE with tilt, swivel, screen rotation, VESA support and cable management for flexible, ergonomic desktop setups.', 'subcategories/seo/Articulating_Monitor_Arm.jpg', 'Articulating Monitor Arms UAE', 'Articulating Monitor Arms UAE | Ergonomic | Skill Tech', 'مفصل رصد الذراع'),
(50, 'Desktop Mount', 'desktop-mount', 'subcategories/desk6cdc2feedcd6607cc1bc4fda5a65773e_cWlS8hq.jpg', 44, 1, 0.000, 0, 'https://skilltechonline.com/desktop-mounts/desktop-mount', 'Buy desktop mounts in UAE with VESA support, swivel and height-adjustable designs for 23–75 inch TVs, with sturdy tabletop bases for home and office use.', 'subcategories/seo/Desktop_Mount.jpg', 'Desktop Mounts UAE', 'Desktop Mounts UAE | Tabletop TV Stands | Skill Tech', 'جبل سطح المكتب'),
(51, 'CPU Mounts', 'cpu-mounts', 'subcategories/cpu5f0e0056c01766df7755951f1839332e.jpg', 59, 1, 0.000, 0, 'https://skilltechonline.com/dvd-receiver-mounts/cpu-mounts', 'Buy CPU mounts in UAE with adjustable under-desk and wall options, sturdy steel builds, swivel access and space-saving support for organized workstations.', 'subcategories/seo/CPU_Mounts.jpg', 'CPU Mounts UAE', 'CPU Mounts UAE | Adjustable & Space-Saving | Skill Tech', 'يتصاعد وحدة المعالجة المركزية'),
(52, 'Cabinet Indoor', 'cabinet-indoor', 'subcategories/cabinet_intdoor_led_display-0230a92e0f3c4185771e2d6dd53bd72a46_fl6K9is.jpg', 45, 1, 0.000, 0, 'https://skilltechonline.com/led-display/cabinet-indoor', 'Buy indoor LED display cabinets in UAE with P1.2–P2.5 fine pixel pitches, 600-nit brightness, wide viewing angles and slim die-cast aluminium builds.', '', 'Indoor LED Display Cabinets UAE', 'Indoor LED Display Cabinets UAE | Fine Pitch | Skill Tech', 'خزانة داخلية'),
(53, 'Cabinet Outdoor', 'cabinet-outdoor', 'subcategories/19_1a2c789381df04bb7ed2725ad01803244.jpg', 45, 1, 0.000, 0, 'https://skilltechonline.com/led-display/cabinet-outdoor', 'Buy outdoor LED display cabinets in UAE with up to 6000 nits brightness, wide viewing angles, durable metal builds and IP65 protection for outdoor signage.', 'subcategories/seo/Cabinet_Outdoor.jpg', 'Outdoor LED Cabinets UAE', 'Outdoor LED Cabinets UAE | High Brightness | Skill Tech', 'خزانة خارجية'),
(54, 'Module Indoor', 'module-indoor', 'subcategories/LED_Displayab7177a21ec40b6ab8632a4d0058d654.jpg', 45, 1, 0.000, 0, 'https://skilltechonline.com/led-display/module-indoor', 'Buy indoor LED modules in UAE with fine pixel pitches, 400–600 nits brightness, wide viewing angles and brightness correction for seamless display walls.', 'subcategories/seo/Module_Indoor.jpg', 'Indoor LED Modules UAE', 'Indoor LED Modules UAE | Fine Pitch Displays | Skill Tech', 'وحدة داخلية'),
(55, 'Module Outdoor', 'module-outdoor', 'subcategories/18_102bb92102281b8733ae6b0f34b54eec0.jpg', 45, 1, 0.000, 0, 'https://skilltechonline.com/led-display/module-outdoor', 'Buy outdoor LED display modules in UAE with 4500 cd/m² brightness, wide 120° viewing angles and P2.5–P8 pixel pitches for advertising and public displays.', 'subcategories/seo/Module_Outdoor.jpg', 'Outdoor LED Modules UAE', 'Outdoor LED Modules UAE', 'وحدة في الهواء الطلق'),
(57, 'Floor Stands', 'floor-stands', 'subcategories/SH_FS53-46T_walnut_scene-pic_01.jpg', 47, 1, 0.000, 0, 'https://skilltechonline.com/floor-stands-cart/floor-stands', 'TV floor stand Dubai, display stand UAE, studio TV stand, VESA TV stand UAE, media console TV stand', 'subcategories/seo/Floor_Stands.jpg', 'TV Floor Stands UAE', 'TV Floor Stands UAE | Modern Display Stands | Skill Tech', 'المدرجات الأرضية'),
(58, 'TV Cart or Trolley', 'tv-cart-or-trolley', 'subcategories/fs_wh38eae1909e2a5179020923552b5cffbf.jpg', 47, 1, 0.000, 0, 'https://skilltechonline.com/floor-stands-cart/tv-cart-or-trolley', 'Buy TV carts and trolleys in UAE with adjustable height, heavy-duty support, smooth caster mobility and cable management for offices and commercial displays.', 'subcategories/seo/TV_Cart_or_Trolley.jpg', 'TV Carts & Trolleys UAE', 'TV Carts & Trolleys UAE | Mobile Display Stands | Skill Tech', 'عربة التلفزيون أو العربة'),
(59, 'Motorized TV Lift', 'motorized-tv-lift', 'subcategories/montafeb25598aab31192e0ada3d57b84f78b.jpg', 48, 1, 0.020, 0, 'https://skilltechonline.com/motorized-mounts/motorized-tv-lift', 'Buy motorized TV lifts in UAE with app and voice control, pop-up or drop-down motion, 360° swivel and support for large TVs in concealed installations.', 'subcategories/seo/Motorized_TV_Lift.jpg', 'motorized mounts', 'Motorized TV Lift UAE | Smart & Pop-Up Models | Skill Tech', 'رفع تلفزيون بمحرك'),
(60, 'Motorized Projector Screens', 'motorized-projector-screens', 'subcategories/Motorozed_Projector11a02913817a6f6b05a9638636a09336.jpg', 49, 1, 0.000, 0, 'https://skilltechonline.com/projector-screens/motorized-projector-screens', 'Buy motorized projector screens in UAE with remote control, matte white fabric, wide viewing angles and wall or ceiling mounting for professional AV setups.', 'subcategories/seo/Motorized_Projector_Screens.jpg', 'Motorized Projector Screens UAE', 'Motorized Projector Screens UAE | Electric | Skill Tech', 'شاشات عرض بروجكتور بمحرك'),
(61, 'Projector Screen', 'projector-screen', 'subcategories/Projector_Scree32b5a6253dd785a32114795e6a68e2a7.jpg', 49, 1, 0.000, 0, 'https://skilltechonline.com/projector-screens', 'Buy projector screens in UAE, including motorized, manual and tripod options with matte white fabric and wide viewing angles for home and professional use.', 'subcategories/seo/Projector_Screens.jpg', 'Projector Screens UAE', 'Projector Screens UAE | Motorized & Tripod | Skill Tech', 'شاشات بروجكتر'),
(62, 'Tripod Projector Screens', 'tripod-projector-screens', 'subcategories/Tripod_Projector5474d273a7e0aa50363f2bb3e7179634.jpg', 49, 1, 0.000, 0, 'https://skilltechonline.com/projector-screens/tripod-projector-screens', 'Buy tripod projector screens in UAE with a 120-inch 4:3 display, matte white fabric, 160° viewing angle and stable portable stand for presentations.', 'subcategories/seo/Tripod_Projector_Screens.jpg', 'Tripod Projector Screens UAE', 'Tripod Projector Screens UAE | Portable 120in | Skill Tech', 'شاشات عرض ترايبود'),
(63, 'Projector Ceiling Mounts', 'projector-ceiling-mounts', 'subcategories/SH_08PB_scene_2.jpg', 50, 1, 0.000, 0, 'https://skilltechonline.com/projector-mounts/projector-ceiling-mounts', 'Buy projector ceiling mounts in UAE with heavy-duty support, adjustable tilt, swivel, extension ranges and cable management for home and professional AV setups.', 'subcategories/seo/Projector_Ceiling_Mounts.jpg', 'Projector Ceiling Mounts UAE', 'Projector Ceiling Mounts UAE | Heavy-Duty | Skill Tech', 'حوامل سقف جهاز العرض'),
(64, 'Projector Floor Stands', 'projector-floor-stands', 'subcategories/SH_TS08-scene_01.jpg', 50, 1, 0.000, 0, 'https://skilltechonline.com/projector-mounts/projector-floor-stands', 'Buy projector floor stands in UAE with adjustable height, 10kg support, tilting platform and mobile casters for offices, classrooms and presentations.', 'subcategories/seo/Projector_Floor_Stands.jpg', 'Projector Floor Stands UAE', 'Projector Floor Stands UAE | Mobile Trolley | Skill Tech', 'حوامل أرضية لجهاز العرض'),
(65, 'Non Smart LED TV', 'normal', 'subcategories/32_inch_normal_tv3294a2d82696d9c6e5edede7a8489ce6.jpg', 51, 1, 0.000, 0, 'https://skilltechonline.com/tv/normal', 'Buy Non Smart LED TVs in UAE with HD and Full HD options, frameless designs, wide viewing angles, HDMI and USB connectivity for everyday viewing.', 'subcategories/seo/Non_Smart_LED_TV.jpg', 'Non Smart LED TV UAE', 'Non Smart LED TV UAE | HD & Full HD Models | Skill Tech', 'طبيعي'),
(66, 'Smart LED TV', 'smart-tv', 'subcategories/55_inch_smart_tv0f5ac51110d65011f3c43a9330970e54.jpg', 51, 1, 0.000, 0, 'https://skilltechonline.com/tv/smart-tv', 'Buy Smart LED TVs in UAE with 4K UHD resolution, frameless designs, wide viewing angles, HDMI, USB and RJ45 connectivity for modern home entertainment.', 'subcategories/seo/Smart_LED_TV.jpg', 'Smart LED TV UAE', 'Smart LED TV UAE | 4K UHD & Frameless Models | Skill Tech', 'تلفزيون ذكي'),
(67, 'Gaming Desk', 'gaming-desk', 'subcategories/8_134be3f9aa0dbb9d41f83a88701fdb4c8_qiJzHHO.jpg', 52, 1, 0.000, 0, 'https://skilltechonline.com/gaming/gaming-desk', 'Buy gaming desks in UAE with RGB lighting, sit-stand adjustment, sturdy steel frames and built-in accessories. Explore models for Dubai gaming setups.', 'subcategories/seo/Gaming_Desk.jpg', 'RGB gaming desk UAE, gaming desk Dubai, sit-stand gaming desk, gaming desk supplier UAE', 'Gaming Desk UAE | RGB & Sit-Stand Models | Skill Tech', 'مكتب الألعاب'),
(68, 'Gaming Chair', 'gaming-chair', 'subcategories/7_1eb580a8ce4be487de8615bb54e61dfac.jpg', 52, 1, 1.000, 0, 'https://skilltechonline.com/gaming/gaming-chair', 'Buy gaming chairs in UAE with lumbar support, headrests, PU/PVC upholstery and selected footrests. Explore ergonomic seating for Dubai gaming setups.', 'subcategories/seo/Gaming_Chair.jpg', 'Ergonomic gaming chair UAE, gaming chair Dubai, premium gaming chair UAE, lumbar support gaming chair', 'Gaming Chair UAE | Ergonomic & Premium | Skill Tech', 'كرسي الألعاب'),
(69, 'kiosk screen', 'kiosk-screen', 'subcategories/1-02.jpg', 53, 0, 0.000, 0, 'https://skilltechonline.com/kiosk-screen', 'Discover a wide range of kiosk stands perfect for retail, events, and exhibitions. Our durable and versatile stands offer optimal functionality and sleek design. Shop now for the best solutions to showcase your technology and products.', '', 'Premium Kiosk Stands - Durable & Versatile Solutions', 'Kiosk Stands', 'شاشة كشك'),
(70, 'Tablet Stands', 'tablet-mounts', 'subcategories/tab1d4d64f8b9a686d83e4a7ee150382b5f.jpg', 66, 1, 0.000, 0, 'https://skilltechonline.com/laptop-tablet-stands/tablet-mounts', 'Explore secure tablet and iPad stands in the UAE, including desk, floor, wall and kiosk mounts with adjustable viewing for offices and commercial spaces.', 'subcategories/seo/Tablet_Stands.jpg', 'tablet stand UAE, iPad stand UAE, tablet holder, iPad holder, tablet floor stand, tablet kiosk stand', 'Tablet & iPad Stands UAE | Secure Mounts | Skill Tech', 'حاملات التابلت'),
(71, 'TV Ceiling Mount', 'tv-ceiling-mount', 'subcategories/tv_cebb8cba1da86a413bec8ffe9fde05f19b.jpg', 55, 1, 0.000, 0, 'https://skilltechonline.com/tv-ceiling-mounts/tv-ceiling-mounts', 'Buy TV ceiling mounts in UAE with heavy-duty steel builds, adjustable height, tilt, swivel and cable management for home and commercial displays.', 'subcategories/seo/TV_Ceiling_Mounts.jpg', 'TV Ceiling Mounts UAE', 'TV Ceiling Mounts UAE | Heavy-Duty & Telescopic | Skill Tech', 'حوامل سقف للتلفزيون'),
(72, 'POS Stands', 'pos-stands', 'subcategories/SH_006PS_scene.jpg', 56, 1, 0.000, 0, 'https://skilltechonline.com/pos-mounts/pos-stands', 'Buy POS stands in UAE with swivel, tilt, rotation and cable management for secure credit card terminals, monitors and organized checkout counters.', 'subcategories/seo/POS_Stands.jpg', 'POS Stands UAE', 'POS Stands UAE | Adjustable Payment Mounts | Skill Tech', 'مواقف نقاط البيع'),
(73, 'Digital Signage Wall Mounts', 'digital-signage-wall-mounts', 'subcategories/img2.jpg', 57, 1, 0.000, 0, 'https://skilltechonline.com/video-wall-mounts/digital-signage-wall-mounts', 'Buy digital signage wall mounts in UAE with pop-out and quick-release designs, VESA compatibility and fine adjustment for professional video walls.', 'subcategories/seo/Digital_Signage_Wall_Mounts.jpg', 'Digital Signage Wall Mounts UAE', 'Digital Signage Wall Mounts UAE | Video Wall | Skill Tech', 'حوامل حائط للافتات الرقمية'),
(74, '2K HDMI Cables', 'hdmi-cables', 'subcategories/HDMI_Cable_lLk34Ty.png', 58, 1, 0.000, 0, 'https://skilltechonline.com/hdmi-cables/hdmi-cables', 'Buy 2K HDMI cables in UAE with 2560 × 1440 support, high-speed Ethernet, gold-plated connectors and foil shielding for reliable home and professional AV.', 'subcategories/seo/2K_HDMI_Cables.jpg', '2K HDMI Cables UAE', '2K HDMI Cables UAE | High-Speed Ethernet | Skill Tech', '2K كابلات اتش دي ام اي'),
(75, 'CAT6+ Patch Cable', 'cat6-patch-cable', 'subcategories/Icon_CAT6_Patch_Cable.jpg', 68, 1, 1.000, 0, 'https://skilltechonline.com/cat6-patch-cable/cat6-patch-cable', 'Buy CAT6+ patch cables in UAE with Gigabit Ethernet support, high data transfer rates and stable copper networking for routers, switches, PCs and offices.', 'subcategories/seo/CAT6_Patch_Cable.jpg', 'CAT6+ Patch Cable UAE', 'CAT6+ Patch Cable UAE | Gigabit Ethernet | Skill Tech', 'كات6 + كابل التصحيح'),
(76, 'DVD Receiver Mounts', 'dvd-or-receiver-mounts', 'subcategories/KBT-01A_scene-pic_01.jpg', 59, 1, 0.000, 0, 'https://skilltechonline.com/dvd-receiver-mounts/dvd-or-receiver-mounts', 'Buy DVD receiver mounts in UAE with steel and tempered-glass shelves, up to 12kg support, compact profiles and space-saving wall installation for AV devices.', 'subcategories/seo/DVD_Receiver_Mounts.jpg', 'DVD Receiver Mounts UAE', 'DVD Receiver Mounts UAE | AV Wall Shelves | Skill Tech', 'يتصاعد جهاز استقبال DVD'),
(77, 'CCTV Camera Brackets', 'ceilling-mounts', 'subcategories/CCTV_Mounts.jpg', 60, 1, 0.000, 0, 'https://skilltechonline.com/cctv-camera-brackets/ceilling-mounts', 'Buy CCTV camera brackets in UAE for dome and bullet cameras, with adjustable mounts, durable metal construction and options for wall or ceiling installation.', 'subcategories/seo/CCTV_Camera_Brackets.jpg', 'CCTV Camera Brackets UAE', 'CCTV Camera Brackets UAE | Mounts & Poles | Skill Tech', 'حاملات كاميرات المراقبة'),
(78, 'AC Bracket', 'ac-bracket', 'subcategories/AC_Bracket.jpg', 61, 1, 0.000, 0, 'https://skilltechonline.com/ac-brackets/ac-bracket', 'Universal AC wall mount brackets with durable steel construction for residential, commercial and industrial HVAC applications.', 'subcategories/seo/AC_Brackets.jpg', 'AC Outdoor Unit Bracket', 'Heavy Duty AC Brackets | Skill Tech', 'قوس التيار المتردد'),
(79, 'Ergonomic Monitor Arm', 'ergonomic', 'subcategories/Ergonomic_Mount_Cat.jpg', 44, 1, 0.000, 1, 'https://skilltechonline.com/desktop-mounts/ergonomic', 'Professional ergonomic workspace products designed for offices, remote workers, education and commercial environments. Enquire today.', 'subcategories/seo/Ergonomic_Monitor_Arm.jpg', 'Ergonomic Workspace Solutions', 'Ergonomic Workspace Solutions | Skill Tech', 'ذراع شاشة إرجونومي'),
(80, 'Motorized TV Wall Mounts', 'motorized-tv-wall-mounts', 'subcategories/LPA53M-481L-scene_01.jpg', 48, 1, 0.000, 0, 'https://skilltechonline.com/motorized-mounts/motorized-tv-wall-mounts', 'Professional motorized TV wall brackets engineered for smart homes, boardrooms, hospitality and commercial display installations.', 'subcategories/seo/Motorized_TV_Wall_Mounts.jpg', 'Motorized TV Wall Mount', 'Motorized TV Wall Mounts | Skill Tech', 'حوامل حائط للتلفزيون بمحرك'),
(81, 'Motorized TV Ceiling Mounts', 'motorized-tv-ceiling-mounts', 'subcategories/SH_M08MW_scene-pic_01.jpg', 48, 1, 3.000, 0, 'https://skilltechonline.com/motorized-mounts/motorized-tv-ceiling-mounts', 'Explore motorized TV ceiling mounts with remote control operation, automated movement and space-saving installation for commercial and residential projects.', 'subcategories/seo/Motorized_Mounts_and_Stands.jpg', 'Motorized TV Ceiling Mount', 'Motorized TV Ceiling Mounts | Skill Tech', 'حوامل سقف للتلفزيون بمحرك'),
(82, 'Motorized TV Cart or Trolly', 'motorized-tv-cart-or-trolly', 'subcategories/SH_TW130_black_scene-pic_01.jpg', 48, 1, 0.001, 0, 'https://skilltechonline.com/motorized-mounts/motorized-tv-cart-or-trolly', 'Explore motorized TV carts with electric height adjustment, smooth mobility and durable construction for conference rooms, education and commercial AV projects.', '', 'Motorized TV Cart', 'Motorized TV Carts & Electric Trolleys | Skill Tech', 'عربة تلفزيون بمحركات أو عربة'),
(83, 'Video Wall Floor Stands', 'video-wall-floor-stands', 'subcategories/03x03VFSN-03.jpg', 57, 1, 0.000, 0, 'https://skilltechonline.com/video-wall-mounts/video-wall-floor-stands', 'Explore floor standing video wall mounts with durable construction, multi-display support and professional AV installation solutions for commercial projects. Enquire today.', 'subcategories/seo/Video_Wall_Mounts.jpg', 'Floor Standing Video Wall Mount', 'Floor Standing Video Wall Mounts | Skill Tech', 'حوامل أرضية حائط الفيديو'),
(85, 'DP Cables to DP Cable', 'dp-cables', 'subcategories/dp_to_dp_cable_oen4tTW.jpg', 67, 1, 3.000, 0, 'https://skilltechonline.com/other-cables/dp-cables', 'Find durable DisplayPort cables for gaming monitors, business workstations and professional AV applications with dependable signal quality.', 'subcategories/seo/DP_Cables_to_DP_Cable.jpg', 'DisplayPort Cable', 'DisplayPort Cables | 4K & 8K AV Connectivity | Skill Tech', 'كابلات دى بى'),
(86, 'Podium Touch Screen', 'podium-touch', 'subcategories/Interactive_digital_map_kiosk_display.png', 64, 1, 0.000, 0, 'https://skilltechonline.com/podium-screen/touch', 'Explore digital presentation podiums combining interactive touch displays, AV integration and smart teaching tools for professional environments.', 'subcategories/seo/Podium_Touch_Screen.jpg', 'Interactive Podium Display', 'Interactive Podium Displays | Skill Tech', 'شاشة منصة تعمل باللمس'),
(87, 'Laptop Stands', 'laptop-stands', 'subcategories/SH_LP-15-scene_01.jpg', 66, 1, 0.000, 0, 'https://skilltechonline.com/laptop-tablet-stands/laptop-stands', 'Buy laptop stands in UAE with adjustable height, foldable designs, 360° rotation and aluminium builds for ergonomic home, office and mobile workspaces.', 'subcategories/seo/Laptop_stand.jpg', 'ergonomic laptop stand UAE, adjustable laptop stand Dubai', 'Laptop Stands UAE | Ergonomic & Adjustable | Skill Tech', 'تقف الكمبيوتر المحمول'),
(90, '4K 30 HZ', '4k-30-hz', 'subcategories/HDMI_Cable_Image.png', 58, 1, 0.100, 0, 'https://skilltechonline.com/hdmi-cables/4k-30-hz', 'Buy 4K 30Hz HDMI cables in UAE with Ethernet, gold-coloured connectors, aluminium foil shielding and durable PVC jackets for home and professional AV setups.', 'subcategories/seo/4K_30_HZ.jpg', '4K 30Hz HDMI Cables UAE', '4K 30Hz HDMI Cables UAE | High-Speed AV | Skill Tech', '4K بتردد 30 هرتز'),
(91, '4K 30 HZ  Copper', '4k-30-hz-copper', 'subcategories/HDMI_CABLE.png', 58, 1, 0.200, 0, 'https://skilltechonline.com/hdmi-cables/4k-30-hz-copper', 'Buy 4K 30Hz copper HDMI cables in UAE with Ethernet support and oxygen-free copper conductors for reliable 4K, 2K and 1080p audio-video connections.', 'subcategories/seo/4K_30_HZ_Copper.jpg', '4K 30Hz Copper HDMI Cables UAE', '4K 30Hz Copper HDMI Cables UAE | High Speed | Skill Tech', '4K بمعدل 30 هرتز نحاس'),
(92, '4K 60 HZ', '4k-60-hz', 'subcategories/HDMI_CABLE_ZgAQJsF.png', 58, 1, 0.300, 0, 'https://skilltechonline.com/hdmi-cables/4k-60-hz', 'Buy 4K HDMI cables in UAE with Ethernet, gold-coloured connectors, aluminium foil shielding and durable PVC jackets for home and professional AV setups.', 'subcategories/seo/4K_60_HZ.jpg', '4K 60Hz HDMI Cables UAE', '4K 60Hz HDMI Cables UAE | High-Speed AV | Skill Tech', '4K بمعدل 60 هرتز'),
(93, '4K 60 HZ Copper', '4k-60-hz-copper', 'subcategories/HDMI_CABLE_goxvXP8.png', 58, 1, 0.500, 0, 'https://skilltechonline.com/hdmi-cables/4k-60-hz-copper', 'Buy 4K 60Hz copper HDMI cables in UAE with Ethernet, oxygen-free tinned copper, gold-coloured connectors and foil shielding for dependable AV connections.', 'subcategories/seo/4K_60_HZ_Copper.jpg', '4K 60Hz Copper HDMI Cables UAE', '4K 60Hz Copper HDMI Cables UAE | Skill Tech Supplier', '4K بمعدل 60 هرتز نحاس'),
(94, '8K 120 HZ Copper', '8k-120-hz-copper', 'subcategories/HDMI_CABLE_prUn1MD.png', 58, 1, 0.600, 0, 'https://skilltechonline.com/hdmi-cables/8k-120-hz-copper', 'Buy 8K 120Hz copper HDMI cables in UAE with tinned copper conductors, gold-coloured connectors, foil shielding and PVC jackets for reliable AV setups.', 'subcategories/seo/8K_120_HZ_Copper.jpg', '8K 120Hz Copper HDMI Cables UAE', '8K 120Hz Copper HDMI Cables UAE | High Speed | Skill Tech', '8K بمعدل 120 هرتز نحاس'),
(95, '4K Fiber', '4k-fiber', 'subcategories/HDMI_CABLE_0xUxtSg.png', 58, 1, 0.700, 0, 'https://skilltechonline.com/hdmi-cables/4k-fiber', 'Buy 4K fiber HDMI cables in UAE with AOC technology, 4K 60Hz support, gold-coloured connectors, foil shielding and 10–50m lengths for professional AV.', 'subcategories/seo/4K_Fiber.jpg', '4K Fiber HDMI Cables UAE', '4K Fiber HDMI Cables UAE | Active Optical 60Hz | Skill Tech', '4K ألياف'),
(96, '8K Fiber', '8k-fiber', 'subcategories/HDMI_CABLE_HlHrNtx.png', 58, 1, 0.800, 0, 'https://skilltechonline.com/hdmi-cables/8k-fiber', 'Buy 8K fiber HDMI cables in UAE with AOC technology, up to 8K 120Hz support, Ethernet, foil shielding and 10–100m options for reliable long-distance AV.', 'subcategories/seo/8K_Fiber.jpg', '8K Fiber HDMI Cables UAE', '8K Fiber HDMI Cables UAE | AOC & Ethernet | Skill Tech', '8K ألياف'),
(98, 'DP to HDMI Copper', 'dp-to-hdmi-copper', 'subcategories/HDMI_CABLE_29hxSE6.png', 67, 1, 0.000, 0, 'https://skilltechonline.com/other-cables/dp-to-hdmi-copper', 'Buy DP to HDMI copper cables in UAE with 4K 30Hz support, oxygen-free tinned copper, gold-coloured connectors and foil shielding for stable AV links.', 'subcategories/seo/DP_Cables.jpg', 'DP to HDMI Copper Cables UAE', 'DP to HDMI Copper Cables UAE | 4K 30Hz | Skill Tech', 'من ديسبلاي بورت إلى إتش دي إم آي | نحاس'),
(99, '8K 60HZ', '8k-60hz', 'subcategories/image.png', 58, 1, 0.400, 0, 'https://skilltechonline.com/hdmi-cables/8k-60hz', 'Buy 8K 60Hz HDMI cables in UAE with Ethernet support, gold-coloured connectors, aluminium foil shielding and durable PVC jackets for home and professional AV.', 'subcategories/seo/8K_60HZ.jpg', '8K 60Hz HDMI Cables UAE', '8K 60Hz HDMI Cables UAE | High-Speed AV | Skill Tech', 'دقة 8K بتردد 60 هرتز'),
(100, 'Kiosk Touch Screen', 'kiosk-touch', 'subcategories/Kiosk-Touch_HVJe8uI.png', 53, 1, 1.000, 0, 'https://skilltechonline.com/kiosk-screen/kiosk-touch', 'Buy kiosk touch screens in UAE with 43 to 65 inch 4K displays, responsive IR touch, Android OS and durable designs for retail and commercial spaces.', 'subcategories/seo/Kiosk_Touch_Screen.jpg', 'Kiosk Touch Screen UAE | 4K Interactive Kiosks | Skill Tech', 'Kiosk Touch Screen UAE | 4K Interactive Kiosks | Skill Tech', 'شاشة لمس للكشك'),
(101, 'Kiosk Non Touch Screen', 'kiosk-non-touch', 'subcategories/Kiosk-Non-Touch_acct9fA.png', 53, 1, 2.000, 0, 'https://skilltechonline.com/kiosk-screen/kiosk-non-touch', 'Buy kiosk non touch screens in UAE with 43–65 inch 4K displays, Android OS, CMS support, HDMI, USB and Bluetooth for indoor digital signage.', 'subcategories/seo/Kiosk_Non_Touch_Screen.jpg', 'Kiosk Screen UAE, Digital Kiosk UAE, 4K Kiosk Dubai, Non Touch Kiosk', 'Kiosk Non Touch Screen UAE | 4K Digital Kiosks | Skill Tech', 'شاشة غير لمسية للكشك'),
(102, 'Wall Mount Rack', 'wall-mount-rack', 'subcategories/image_11.png', 63, 1, 1.000, 0, 'https://skilltechonline.com/other-mounts-accessories/wall-mount-rack', 'Buy wall mount racks in UAE for network and server equipment, with steel construction, lockable glass doors, ventilation and cable management options.', 'subcategories/seo/Wall_Mount_Rack.jpg', 'Wall Mount Rack UAE', 'Wall Mount Rack UAE | Network & Server Racks | Skill Tech', 'حامل رف جداري');
